#!/usr/bin/env bash
set -Eeuo pipefail

# MTProto Proxy Panel v1.3 — Direct Runtime: telemt 3.4.13,
# startup-aware Direct readiness, correct tg_connect placement and manual-only Cascade.
# Запуск: sudo bash mtproto-panel-v1.3.sh

readonly SCRIPT_VERSION="1.3"
readonly SCRIPT_NAME="mtproto-panel-v${SCRIPT_VERSION}.sh"
readonly TMP_PREFIX="/tmp/mtproto-panel-v${SCRIPT_VERSION}.XXXXXX"
readonly INSTALL_DIR_NAME="mtproto-panel-v${SCRIPT_VERSION}"
readonly PAYLOAD_SHA256="5dfac810feec5c77e0328fa929dea8d8e9bc1ff0db9bff76981c7089d6c72aed"

readonly REQUIRED_CMDS=(mktemp rm base64 sha256sum awk tar bash id grep)

umask 077

log() { printf '[%s] %s\n' "$SCRIPT_NAME" "$*" >&2; }
die() { log "ERROR: $*"; exit 1; }

[[ ${EUID:-$(id -u)} -eq 0 ]] || die "Run this installer as root (sudo bash ${SCRIPT_NAME})"

require_cmd() {
  local cmd="$1"
  command -v "$cmd" >/dev/null 2>&1 || die "Required command not found: $cmd"
}

for cmd in "${REQUIRED_CMDS[@]}"; do
  require_cmd "$cmd"
done

TMP_DIR="$(mktemp -d "$TMP_PREFIX")" || die "Failed to create temporary directory"
readonly TMP_DIR
readonly PAYLOAD="$TMP_DIR/payload.tar.gz"

cleanup() { rm -rf "$TMP_DIR" 2>/dev/null || true; }
trap cleanup EXIT

base64 -d > "$PAYLOAD" <<'__MT_PANEL_PAYLOAD__'
