+vP05+nP05+nP09/nv48/Xn68/Tn6c/Tn5Sf/x9Sz6kXALgLAA==
__MT_PANEL_PAYLOAD__

CALC_SHA256="$(sha256sum "$PAYLOAD" | awk '{print $1}')"
[[ "$CALC_SHA256" == "$PAYLOAD_SHA256" ]] || die "Payload checksum mismatch: expected $PAYLOAD_SHA256 got $CALC_SHA256"

# Defense in depth: reject archive traversal and links before extracting as root.
if ! tar -tzf "$PAYLOAD" | awk 'BEGIN{bad=0} /(^\/|(^|\/)\.\.($|\/))/{bad=1} END{exit bad}'; then
  die "Unsafe payload path detected"
fi
if ! tar -tvzf "$PAYLOAD" | awk '$1 ~ /^[lh]/ {bad=1} END{exit bad}'; then
  die "Unsafe payload link detected"
fi

tar --no-same-owner --no-same-permissions -xzf "$PAYLOAD" -C "$TMP_DIR" || die "Failed to unpack payload"
INSTALLER_ROOT="$TMP_DIR/$INSTALL_DIR_NAME"
[[ -f "$INSTALLER_ROOT/install.sh" ]] || die "install.sh not found in payload"

# Не используем exec: иначе trap cleanup EXIT не удалит временный payload.
bash "$INSTALLER_ROOT/install.sh" "$@"
